steps.code:
// Transform and save APOD to Supabase
return [{
  json: {
    title: $node["Fetch APOD"].json.title,
    event_type: 'apod',
    description: $node["Fetch APOD"].json.explanation,
    event_date: new Date($node["Fetch APOD"].json.date),
    source_url: $node["Fetch APOD"].json.url,
    updated_at: new Date().toISOString()
  }
}, {
  json: {
    event_type: 'neo',
    title: `${$node["Fetch NEO Feed"].json.count} Near Earth Objects`,
    description: `NEOs between ${$node["Fetch NEO Feed"].json.start_date} and ${$node["Fetch NEO Feed"].json.end_date}`,
    event_date: new Date(),
    source_url: null,
    updated_at: new Date().toISOString()
  }
}]
}
